result = await mcp.call_tool("tools", "ox-bridge-edit", {"path": "/workspace/deadline_retry.py", "edits": [{"old": "    start = clock()
    delay = base_delay
    attempts = 0

    while True:
        # Don't even start an attempt whose budget is already gone.
        elapsed = clock() - start
        if elapsed >= total_budget:
            raise DeadlineExceeded(
                "deadline exceeded after %.6f time units and %d attempt(s)"
                % (elapsed, attempts),
                elapsed=elapsed,
                attempts=attempts,
            )", "new": "    start = clock()
    delay = base_delay
    attempts = 0
    last_error = None

    while True:
        # Don't even start an attempt whose budget is already gone.
        elapsed = clock() - start
        if elapsed >= total_budget:
            raise DeadlineExceeded(
                "deadline exceeded after %.6f time units and %d attempt(s)"
                % (elapsed, attempts),
                elapsed=elapsed,
                attempts=attempts,
            ) from last_error"}, {"old": "        attempts += 1
        try:
            return fn()
        except Exception as exc:
            elapsed = clock() - start", "new": "        attempts += 1
        try:
            return fn()
        except Exception as exc:
            last_error = exc
            elapsed = clock() - start"}]})
